class Solution {
public:
    bool isBipartite(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> color(n, 0);
        for (int i = 0; i < n; ++i) {
            if (color[i] != 0) continue;
            queue<int> q;
            q.push(i);
            color[i] = 1;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : graph[u]) {
                    if (color[v] == color[u]) return false;
                    if (color[v] == 0) {
                        color[v] = -color[u];
                        q.push(v);
                    }
                }
            }
        }
        return true;
    }
};

class Solution {
    public boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        for (int i = 0; i < n; i++) {
            if (color[i] != 0) continue;
            Queue<Integer> q = new LinkedList<>();
            q.add(i);
            color[i] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : graph[u]) {
                    if (color[v] == color[u]) return false;
                    if (color[v] == 0) {
                        color[v] = -color[u];
                        q.add(v);
                    }
                }
            }
        }
        return true;
    }
}

var isBipartite = function(graph) {
    const n = graph.length;
    const color = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        if (color[i] !== 0) continue;
        const q = [i];
        color[i] = 1;
        let head = 0;
        while (head < q.length) {
            const u = q[head++];
            for (const v of graph[u]) {
                if (color[v] === color[u]) return false;
                if (color[v] === 0) {
                    color[v] = -color[u];
                    q.push(v);
                }
            }
        }
    }
    return true;
};
